import{_ as t,H as a,f as r,i}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"编辑加餐｜六张图，带你回顾架构师的六条生存法则","description":"","frontmatter":{},"headers":[{"level":2,"title":"法则一： 02讲、 03讲","slug":"法则一-02讲、-03讲","link":"#法则一-02讲、-03讲","children":[]},{"level":2,"title":"法则二： 04讲、 05讲、 06讲","slug":"法则二-04讲、-05讲、-06讲","link":"#法则二-04讲、-05讲、-06讲","children":[]},{"level":2,"title":"法则三： 07讲、 08讲","slug":"法则三-07讲、-08讲","link":"#法则三-07讲、-08讲","children":[]},{"level":2,"title":"法则四： 09讲、 10讲","slug":"法则四-09讲、-10讲","link":"#法则四-09讲、-10讲","children":[]},{"level":2,"title":"法则五： 11讲、 12讲","slug":"法则五-11讲、-12讲","link":"#法则五-11讲、-12讲","children":[]},{"level":2,"title":"法则六： 13讲","slug":"法则六-13讲","link":"#法则六-13讲","children":[]}],"relativePath":"郭东白的架构课/编辑加餐｜六张图，带你回顾架构师的六条生存法则.md","filePath":"郭东白的架构课/编辑加餐｜六张图，带你回顾架构师的六条生存法则.md","lastUpdated":1779822617000}'),n={name:"郭东白的架构课/编辑加餐｜六张图，带你回顾架构师的六条生存法则.md"};function l(o,e,s,c,g,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="编辑加餐-六张图-带你回顾架构师的六条生存法则" tabindex="-1">编辑加餐｜六张图，带你回顾架构师的六条生存法则 <a class="header-anchor" href="#编辑加餐-六张图-带你回顾架构师的六条生存法则" aria-label="Permalink to &quot;编辑加餐｜六张图，带你回顾架构师的六条生存法则&quot;">​</a></h1><p>你好，我是辰洋，是《郭东白的架构课》的负责人。这是我们在这个专栏的第一次正式会面，你可能会觉得与我有些陌生。不过从我的眼光来看，对于专栏里的每一行字、每一个案例，对于在认真学习、留言打卡的你，我都太熟悉了。</p><p>好了，感性流露到此结束，言归正传。我看到留言区有几位小伙伴反馈：</p><blockquote><p>文章看得很过瘾，不过也有些长，请问可以给一些思维导图吗？</p></blockquote><p>我非常理解你提出这个需求的出发点：阅读完文章后，用一张图直接带走（Take Away）所有知识点。之后回顾专栏时，可以直接看图。毕竟一图胜千言嘛。</p><p>在编辑的角色定义中，其中一个是“用户需求的满足师”。所以，我今天就带着六张图来啦！</p><h2 id="法则一-02讲、-03讲" tabindex="-1">法则一： <a href="https://time.geekbang.org/column/article/463876" target="_blank" rel="noreferrer">02讲</a>、 <a href="https://time.geekbang.org/column/article/464541" target="_blank" rel="noreferrer">03讲</a> <a class="header-anchor" href="#法则一-02讲、-03讲" aria-label="Permalink to &quot;法则一： [02讲](https://time.geekbang.org/column/article/463876)、 [03讲](https://time.geekbang.org/column/article/464541)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/63ef46c685c91b7a9f2115eb041e3224.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/63ef46c685c91b7a9f2115eb041e3224.jpg" alt=""></a></p><h2 id="法则二-04讲、-05讲、-06讲" tabindex="-1">法则二： <a href="https://time.geekbang.org/column/article/467398" target="_blank" rel="noreferrer">04讲</a>、 <a href="https://time.geekbang.org/column/article/467402" target="_blank" rel="noreferrer">05讲</a>、 <a href="https://time.geekbang.org/column/article/470232" target="_blank" rel="noreferrer">06讲</a> <a class="header-anchor" href="#法则二-04讲、-05讲、-06讲" aria-label="Permalink to &quot;法则二： [04讲](https://time.geekbang.org/column/article/467398)、 [05讲](https://time.geekbang.org/column/article/467402)、 [06讲](https://time.geekbang.org/column/article/470232)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/cf006b07803091454a17ccccyy6fc200.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/cf006b07803091454a17ccccyy6fc200.jpg" alt=""></a></p><h2 id="法则三-07讲、-08讲" tabindex="-1">法则三： <a href="https://time.geekbang.org/column/article/470228" target="_blank" rel="noreferrer">07讲</a>、 <a href="https://time.geekbang.org/column/article/472716" target="_blank" rel="noreferrer">08讲</a> <a class="header-anchor" href="#法则三-07讲、-08讲" aria-label="Permalink to &quot;法则三： [07讲](https://time.geekbang.org/column/article/470228)、 [08讲](https://time.geekbang.org/column/article/472716)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/9fyy7ef04a48182aabc089a39fac828f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/9fyy7ef04a48182aabc089a39fac828f.jpg" alt=""></a></p><h2 id="法则四-09讲、-10讲" tabindex="-1">法则四： <a href="https://time.geekbang.org/column/article/472734" target="_blank" rel="noreferrer">09讲</a>、 <a href="https://time.geekbang.org/column/article/474496" target="_blank" rel="noreferrer">10讲</a> <a class="header-anchor" href="#法则四-09讲、-10讲" aria-label="Permalink to &quot;法则四： [09讲](https://time.geekbang.org/column/article/472734)、 [10讲](https://time.geekbang.org/column/article/474496)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/30378e83ce657f6317bf5a1c06cbfc2e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/30378e83ce657f6317bf5a1c06cbfc2e.jpg" alt=""></a></p><h2 id="法则五-11讲、-12讲" tabindex="-1">法则五： <a href="https://time.geekbang.org/column/article/474513" target="_blank" rel="noreferrer">11讲</a>、 <a href="https://time.geekbang.org/column/article/476904" target="_blank" rel="noreferrer">12讲</a> <a class="header-anchor" href="#法则五-11讲、-12讲" aria-label="Permalink to &quot;法则五： [11讲](https://time.geekbang.org/column/article/474513)、 [12讲](https://time.geekbang.org/column/article/476904)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/791f61536c023ecb351d6cfbde033921.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/791f61536c023ecb351d6cfbde033921.png" alt=""></a></p><h2 id="法则六-13讲" tabindex="-1">法则六： <a href="https://time.geekbang.org/column/article/476909" target="_blank" rel="noreferrer">13讲</a> <a class="header-anchor" href="#法则六-13讲" aria-label="Permalink to &quot;法则六： [13讲](https://time.geekbang.org/column/article/476909)&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/ffc7aa8d1eb93a04cea231e3d25fc912.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%83%AD%E4%B8%9C%E7%99%BD%E7%9A%84%E6%9E%B6%E6%9E%84%E8%AF%BE/images/479535/ffc7aa8d1eb93a04cea231e3d25fc912.jpg" alt=""></a></p><p>看完图，细心的你可能发现了，我画的并不是思维导图，也不是什么框架图，而是以文章逻辑来构造的长图文（而且图里主要是文字）。</p><p>正如东白老师在14讲中所说的，这门课中所谓的“知识点”，是为大多数人所熟知的，也是很容易理解的。但想要掌握这些的关键就在于“案例”。这也是为什么我们这个专栏的每篇文章都比较长，目的是想让你在学习法则时要着重通过案例去理解。当然，如果这些案例能勾连出你过往的经历或案例，从而启发你的思考，那这就是我和东白老师期待中的惊喜了。</p><p>最后，如果关于专栏，你有什么建议或更好的想法，欢迎你分享在留言区或读者交流群，我会常常关注，继续满足你的需求！</p><p>最后的最后，如果你觉得这门课对你有所帮助的话，欢迎你把课程分享给同事或朋友，我们共同学习进步！</p>',22)])])}const m=t(n,[["render",l]]);export{b as __pageData,m as default};
